mapper.select:
SELECT CLOSE_PRICE FROM (
select
MID_PRICE,rank() OVER(PARTITION BY EXCHARGE_CODE ORDER BY TRADE_DATE DESC ) AS rowno
from MST_EXCHARGE_QUOTE  WHERE TRADE_DATE <= #{valDate, jdbcType=DATE}
AND QUOT_CYY = #{quotCcy}
AND BASIS_CYY = #{basisCcy}
) WHERE ROWNO =1

SELECT SEC_ID,PRICE,NETPRICE,M_DURATION,BPYIELD,LAST_PERIOD FROM (
select
MVI.SEC_ID,MVI.PRICE,MVI.NETPRICE,MVI.M_DURATION,MVI.BPYIELD,MVI.LAST_PERIOD,rank() OVER(PARTITION BY MVI.SEC_ID ORDER BY MVI.VALUE_DATE DESC ) AS rowno
from MST_BOND_VALUATION_INFO MVI
INNER JOIN FIN_PRODUCT FP ON MVI.SEC_ID=FP.FINPROD_MARKET_ID
 WHERE MVI.VALUE_DATE <= #{valDate, jdbcType=DATE}

	and FP.FINPROD_ID in

		#{item}


) WHERE ROWNO =1

SELECT PORTFOLIO_ID,TDY_ASSET_NETVALUE,TDY_ASSET_VALUE FROM ( SELECT PORTFOLIO_ID,TDY_ASSET_NETVALUE,TDY_ASSET_VALUE, RANK() OVER(PARTITION BY PORTFOLIO_ID ORDER BY CDATE desc) AS rowno FROM PTL_PORTFOLIO_VALUATION ppv WHERE CDATE <= #{valDate, jdbcType=DATE} and nvl(TDY_ASSET_NETVALUE,0)>0
and PORTFOLIO_ID in
#{item}
) WHERE ROWNO =1

SELECT distinct A.PORTFOLIO_ID , A.ACCT_NO , B.REGIST_ORG , B.TRADE_PLACE FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
and A.PORTFOLIO_ID in
#{item}
AND B.TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}
AND B.REGIST_ORG = #{registOrg, jdbcType=VARCHAR}
